-- Arbeitsrecht Berufsbildung > Rechte von Auszubildenden > Schutz vor Diskriminierung (AGG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Hat ein Fachinformatiker Anspruch auf Schutz vor Diskriminierung wegen seines Alters?', 2, '[{"text": "Ja", "correct": true, "because": "Das AGG schützt vor Altersdiskriminierung"}, {"text": "Nein", "correct": false, "because": "Alter ist ein geschütztes Merkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ausbildungsunternehmen einem Fachinformatiker aufgrund seines Geschlechts weniger Vergütung zahlen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 3 AGG verbietet Geschlechtsdiskriminierung"}, {"text": "Ja", "correct": false, "because": "Gleiche Vergütung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker Diskriminierung durch Kollegen im Betrieb hinnehmen?', 2, '[{"text": "Nein", "correct": true, "because": "Der Betrieb muss laut AGG schützen"}, {"text": "Ja", "correct": false, "because": "Diskriminierung ist unzulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Ausbilder einen Fachinformatiker wegen seiner Religion von Projekten ausschließen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 3 AGG schützt vor Religionsdiskriminierung"}, {"text": "Ja", "correct": false, "because": "Diskriminierung ist verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker bei Diskriminierung Beschwerde bei der Antidiskriminierungsstelle einreichen?', 2, '[{"text": "Ja", "correct": true, "because": "Das AGG sieht externe Hilfe vor"}, {"text": "Nein", "correct": false, "because": "Beschwerderecht besteht"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz schützt einen Fachinformatiker vor Diskriminierung im Betrieb?', 2, '[{"text": "Allgemeines Gleichbehandlungsgesetz", "correct": true, "because": "Das AGG ist dafür zuständig"}, {"text": "Berufsbildungsgesetz", "correct": false, "because": "BBiG regelt Ausbildung"}, {"text": "Arbeitsschutzgesetz", "correct": false, "because": "ArbSchG regelt Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn er im Betrieb diskriminiert wird?', 3, '[{"text": "Den Vorfall melden und den Betrieb informieren", "correct": true, "because": "§ 13 AGG fordert Beschwerde"}, {"text": "Es ignorieren", "correct": false, "because": "Ignorieren schützt nicht"}, {"text": "Sofort kündigen", "correct": false, "because": "Nicht die erste Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal ist laut AGG nicht geschützt?', 3, '[{"text": "Programmierkenntnisse", "correct": true, "because": "Kein AGG-Merkmal"}, {"text": "Ethnische Herkunft", "correct": false, "because": "Geschützt nach § 3 AGG"}, {"text": "Behinderung", "correct": false, "because": "Geschützt nach § 3 AGG"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, einen Fachinformatiker vor Diskriminierung zu schützen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 12 AGG legt Schutzpflichten fest"}, {"text": "Die IHK", "correct": false, "because": "IHK überwacht nur"}, {"text": "Die Kollegen", "correct": false, "because": "Pflicht liegt beim Betrieb"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht einem Betrieb bei Diskriminierung eines Fachinformatikers?', 3, '[{"text": "Schadensersatzansprüche", "correct": true, "because": "§ 15 AGG sieht Entschädigung vor"}, {"text": "Automatische Schließung", "correct": false, "because": "Keine direkte Folge"}, {"text": "Verlust der IHK-Mitgliedschaft", "correct": false, "because": "Nicht vorgesehen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale schützt das AGG für einen Fachinformatiker?', 4, '[{"text": "Geschlecht", "correct": true, "because": "§ 3 AGG schützt Geschlecht"}, {"text": "Religion", "correct": true, "because": "Geschützt nach § 3 AGG"}, {"text": "Programmierfähigkeiten", "correct": false, "because": "Kein AGG-Merkmal"}, {"text": "Ethnische Herkunft", "correct": true, "because": "Geschützt nach § 3 AGG"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Handlungen könnten Diskriminierung eines Fachinformatikers darstellen?', 3, '[{"text": "Weniger Vergütung wegen Alter", "correct": true, "because": "Verstoß gegen § 3 AGG"}, {"text": "Ausschluss von Projekten wegen Behinderung", "correct": true, "because": "Verstoß gegen § 3 AGG"}, {"text": "Kritik an Programmierfehlern", "correct": false, "because": "Leistungsbezogen, keine Diskriminierung"}, {"text": "Beleidigungen wegen Herkunft", "correct": true, "because": "Verstoß gegen § 3 AGG"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen kann ein Fachinformatiker bei Diskriminierung ergreifen?', 4, '[{"text": "Betriebliche Beschwerde einreichen", "correct": true, "because": "§ 13 AGG fordert dies"}, {"text": "Antidiskriminierungsstelle kontaktieren", "correct": true, "because": "Externe Unterstützung möglich"}, {"text": "Es hinnehmen", "correct": false, "because": "Nicht empfohlen"}, {"text": "Klage vor Gericht einreichen", "correct": true, "because": "§ 15 AGG erlaubt Schadensersatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten hat ein Ausbildungsbetrieb laut AGG gegenüber einem Fachinformatiker?', 3, '[{"text": "Diskriminierung verhindern", "correct": true, "because": "§ 12 AGG verpflichtet dazu"}, {"text": "Beschwerden entgegennehmen", "correct": true, "because": "§ 13 AGG schreibt es vor"}, {"text": "Jeden Wunsch erfüllen", "correct": false, "because": "Nicht AGG-bezogen"}, {"text": "Schutzmaßnahmen umsetzen", "correct": true, "because": "§ 12 AGG verlangt Prävention"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gilt als Diskriminierung eines Fachinformatikers im Sinne des AGG?', 3, '[{"text": "Abwertende Kommentare über das Geschlecht", "correct": true, "because": "Verstoß gegen § 3 AGG"}, {"text": "Weniger Aufgaben wegen Religion", "correct": true, "because": "Verstoß gegen § 3 AGG"}, {"text": "Kritik an fehlenden Kenntnissen", "correct": false, "because": "Leistungsbezogen"}, {"text": "Keine Beförderung wegen Alter", "correct": true, "because": "Verstoß gegen § 3 AGG"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das AGG schützt nur Vollzeit-Auszubildende. b) Ein Fachinformatiker kann Schadensersatz fordern.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "AGG gilt für alle"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "§ 15 AGG erlaubt Schadensersatz"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Diskriminierung wegen Behinderung ist laut AGG verboten. b) Der Betrieb muss Diskriminierung aktiv verhindern.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 3 und § 12 AGG bestätigen dies"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker kann wegen seiner ethnischen Herkunft benachteiligt werden. b) Das AGG gilt auch für Kollegen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) widerspricht AGG"}, {"text": "Nur b) stimmt", "correct": true, "because": "AGG schützt vor Kollegen (§ 12)"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Diskriminierung ist nur strafbar, wenn sie öffentlich ist. b) Ein Fachinformatiker hat Anspruch auf Entschädigung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "§ 15 AGG sieht Entschädigung vor"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das AGG schützt vor Diskriminierung wegen sexueller Orientierung. b) Der Betrieb ist nicht verantwortlich für Diskriminierung durch Kunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "§ 3 AGG schützt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) widerspricht § 12 AGG"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

